using System;using System.Collections.Generic;using System.ComponentModel.DataAnnotations;using System.ComponentModel.DataAnnotations.Schema;using CodeShellCore.Data;using CodeShellCore.Notifications;namespace CodeShellCore.Notifications.Users{    [Table("Users", Schema = "Note")]    public partial class User : AuditedEntity<long>, IEditable    {        public User()        {            Notifications = new HashSet<Notification>();        }        [StringLength(150)]        public string Name { get; set; }        [StringLength(150)]        public string Email { get; set; }        [StringLength(50)]        public string Mobile { get; set; }        public int UserType { get; set; }        public long? PersonId { get; set; }        [StringLength(3)]        public string PreferredLanguage { get; set; }
        [NotMapped]        public string State { get; set; }        [InverseProperty("User")]        public ICollection<Notification> Notifications { get; set; }    }}